import type { CaptionItem } from 'components/Chart/components/Legend/Legend';

import type { OverTimePerformanceBigNumber } from '../components/OverTimePerformance/types';
import type {
  PosPerformanceBarDataset,
  PosPerformanceChartData,
  PosPerformanceTableRow,
} from '../components/PosPerformance/types';

export const POS_TOOL_OVERVIEW_COMPONENT_ID = 'overtime-performance';

const CARDS_KEY = 'overtime-performance';
const COMPARISON_KEY = 'overtime-comparison';

const POS_PERFORMANCE_CHART_PRESENTATION = {
  chartTitle: 'POS Over time Comparison',
  measure: '[%]',
  chartHeaderTooltip: {
    title: 'POS Over time Comparison (i):',
    text: "This chart compares Participation, Occasions, and Servings over time. The bars show each metric's change vs last year (delta vs LY) for each period. The table under the chart shows the actual current values (AC) for the same periods.",
  },
  legend: [
    {
      label: 'Participation',
      color: 'rgba(235, 180, 0, 1)',
      border: 'rgba(20, 20, 20, 0.16)',
      pointStyle: 'roundedRectangle',
    },
    {
      label: 'Occasions',
      color: 'rgba(112, 198, 255, 1)',
      border: 'rgba(20, 20, 20, 0.16)',
      pointStyle: 'roundedRectangle',
    },
    {
      label: 'Servings',
      color: 'rgba(201, 175, 130, 1)',
      border: 'rgba(20, 20, 20, 0.16)',
      pointStyle: 'roundedRectangle',
    },
  ] as CaptionItem[],
} as const;

type RawOverview = Record<string, unknown> | null | undefined;

type RawComparison = {
  empty?: boolean;
  labels?: string[];
  datasets?: PosPerformanceBarDataset[];
  comparison?: { rows?: PosPerformanceTableRow[] };
};

const isEmptyMarker = (value: unknown): boolean =>
  !!value &&
  typeof value === 'object' &&
  ((value as Record<string, unknown>)['#empty'] === true ||
    (value as Record<string, unknown>).empty === true);

export function mapOverTimePerformanceCards(
  overview: RawOverview,
): OverTimePerformanceBigNumber[] | undefined {
  const raw = overview?.[CARDS_KEY];

  if (!Array.isArray(raw)) {
    return undefined;
  }

  return raw.map((card) => ({
    ...card,
    data: Array.isArray(card?.data) ? card.data : [],
  })) as OverTimePerformanceBigNumber[];
}

export function mapPosPerformanceChart(
  overview: RawOverview,
): PosPerformanceChartData | null {
  const raw = overview?.[COMPARISON_KEY] as RawComparison | undefined;

  if (!raw || isEmptyMarker(raw) || !raw.labels?.length) {
    return null;
  }

  return {
    ...POS_PERFORMANCE_CHART_PRESENTATION,
    labels: raw.labels,
    datasets: raw.datasets ?? [],
    comparison: { rows: raw.comparison?.rows ?? [] },
  };
}
